const { registerBlockType } = wp.blocks;
const { RichText, MediaUpload, MediaUploadCheck } = wp.blockEditor;
const { Button } = wp.components;

registerBlockType( 'custom-block/custom-block', {
    title: 'Custom Block',
    icon: 'format-image',
    category: 'common',
    attributes: {
        heading: {
            type: 'string',
            default: 'Heading'
        },
        paragraph: {
            type: 'string',
            default: 'Paragraph'
        },
        imageUrl: {
            type: 'string',
            default: ''
        },
        imageId: {
            type: 'number',
            default: 0
        }
    },
    edit: function( { attributes, setAttributes } ) {
        const { heading, paragraph, imageUrl, imageId } = attributes;

        function onSelectImage( media ) {
            setAttributes( {
                imageUrl: media.url,
                imageId: media.id
            } );
        }

        return (
            <div className="custom-block">
                <RichText
                    tagName="h2"
                    value={ heading }
                    onChange={ ( value ) => setAttributes( { heading: value } ) }
                    placeholder="Heading"
                />
                <RichText
                    tagName="p"
                    value={ paragraph }
                    onChange={ ( value ) => setAttributes( { paragraph: value } ) }
                    placeholder="Paragraph"
                />
                <MediaUploadCheck>
                    <MediaUpload
                        onSelect={ onSelectImage }
                        type="image"
                        value={ imageId }
                        render={ ( { open } ) => (
                            <Button onClick={ open }>
                                { imageUrl ? 'Change Image' : 'Upload Image' }
                            </Button>
                        ) }
                    />
                </MediaUploadCheck>
                { imageUrl && <img src={ imageUrl } alt="Uploaded" /> }
            </div>
        );
    },
    save: function( { attributes } ) {
        const { heading, paragraph, imageUrl } = attributes;

        return (
            <div className="custom-block">
                <h2>{ heading }</h2>
                <p>{ paragraph }</p>
                { imageUrl && <img src={ imageUrl } alt="Uploaded" /> }
            </div>
        );
    },
} );
